import{_ as o,C as n,o as i,c as l,a2 as t,j as s,E as r}from"./chunks/framework.B_GyVC5q.js";const k=JSON.parse('{"title":"AI actions & tasks","description":"","frontmatter":{"title":"AI actions & tasks"},"headers":[],"relativePath":"guide/ai-actions.md","filePath":"guide/ai-actions.md"}'),d={name:"guide/ai-actions.md"};function c(h,a,p,u,g,m){const e=n("DocScreenshot");return i(),l("div",null,[a[0]||(a[0]=t('<h1 id="ai-actions-tasks" tabindex="-1">AI actions &amp; tasks <a class="header-anchor" href="#ai-actions-tasks" aria-label="Permalink to &quot;AI actions &amp; tasks&quot;">​</a></h1><p>Dataclass-scoped <strong>AI actions</strong> run in the background so you can keep browsing while the model works. Results appear in <strong>AI tasks</strong> on the Status bar.</p><p>These actions require a configured LLM (same settings as the <a href="/4d-dataexplorer/guide/assistant.html">AI assistant</a>).</p><h2 id="open-ai-actions" tabindex="-1">Open AI actions <a class="header-anchor" href="#open-ai-actions" aria-label="Permalink to &quot;Open AI actions&quot;">​</a></h2><p>When an LLM is configured, a sparkles <strong>AI</strong> control appears on:</p><ul><li>Dataclass entity list header</li><li>Sidebar dataclass row</li><li>Structure graph selection</li></ul>',6)),s("p",null,[r(e,{src:"/screenshots/23-ai-actions-menu.png",alt:"AI actions menu"})]),a[1]||(a[1]=t('<p>Choose:</p><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Generate data</strong></td><td>Create sample entities in the selected dataclass</td></tr><tr><td><strong>Ask dataclass</strong></td><td>Filter, inspect, or change data with natural language</td></tr></tbody></table><p>In <strong>read-only mode</strong>, Generate data is disabled. Ask dataclass stays available for read-only work (queries, filters, schema info); write tools are blocked.</p><h2 id="generate-data" tabindex="-1">Generate data <a class="header-anchor" href="#generate-data" aria-label="Permalink to &quot;Generate data&quot;">​</a></h2><ol><li>Open <strong>AI</strong> → <strong>Generate data</strong></li><li>Set how many entities to create (presets or custom count, 1-50)</li><li>Pick one or more styles (hover for hints): <ul><li><strong>Realistic</strong> — production-like values</li><li><strong>Edge cases</strong> — boundaries, empties, extremes, unicode</li><li><strong>Minimal</strong> — required / common fields only</li></ul></li><li>Optionally add extra instructions</li><li>Click <strong>Generate</strong></li></ol>',5)),s("p",null,[r(e,{src:"/screenshots/24-ai-generate-data.png",alt:"Generate data modal"})]),a[2]||(a[2]=t('<p>The task starts immediately and opens in <strong>AI tasks</strong>. After creation, the current view refreshes so new rows appear.</p><h2 id="ask-dataclass" tabindex="-1">Ask dataclass <a class="header-anchor" href="#ask-dataclass" aria-label="Permalink to &quot;Ask dataclass&quot;">​</a></h2><ol><li>Open <strong>AI</strong> → <strong>Ask dataclass</strong></li><li>Describe what you want for the selected table, for example: <ul><li>Show recent records in a new tab</li><li>How many records are there, and what are the main fields?</li><li>Delete all records in this dataclass</li></ul></li><li>Click <strong>Ask</strong> (or pick an example chip)</li></ol>',3)),s("p",null,[r(e,{src:"/screenshots/25-ai-ask-dataclass.png",alt:"Ask dataclass modal"})]),a[3]||(a[3]=t('<p>The agent can:</p><ul><li>Query and summarize the dataclass</li><li>Plan relation analysis first (entity counts → start from the smaller side → minimize requests)</li><li>Chart distributions across relations with <code>@widgets/render</code> (pie/bar/KPI)</li><li>Open filtered results in a <strong>new tab</strong> (entity set / filtered tab)</li><li>Create, update, or delete records when not in read-only mode</li></ul><p>Destructive steps (for example deleting all records) prompt a <strong>confirmation dialog</strong>. Confirm or cancel there to continue the task.</p><h2 id="ai-tasks-history" tabindex="-1">AI tasks history <a class="header-anchor" href="#ai-tasks-history" aria-label="Permalink to &quot;AI tasks history&quot;">​</a></h2><p>Open <strong>AI tasks</strong> from the Status bar (next to Console).</p>',5)),s("p",null,[r(e,{src:"/screenshots/26-ai-tasks-history.png",alt:"AI tasks history"})]),a[4]||(a[4]=t('<ul><li>Running tasks show a spinner and count</li><li>When the agent waits for confirmation, a <strong>dot</strong> appears on <strong>AI tasks</strong></li><li>Open a task to see input, tools &amp; activity, response, and result summary</li><li>Tool rows are collapsed by default; expand a row to inspect args and results</li><li>JSON results render as a compact tree when valid JSON is available</li></ul><h3 id="cancel" tabindex="-1">Cancel <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;Cancel&quot;">​</a></h3><ul><li><strong>Cancel</strong> on the task detail stops that run (including pending confirmations)</li><li><strong>Cancel all</strong> on the task list stops every running task</li><li>Hover a running row for a quick stop control</li></ul><h3 id="clear-history" tabindex="-1">Clear history <a class="header-anchor" href="#clear-history" aria-label="Permalink to &quot;Clear history&quot;">​</a></h3><p>Use <strong>Clear</strong> to remove finished tasks from local history. Running tasks are not persisted across app reloads; interrupted runs are marked cancelled.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Prefer <strong>Ask dataclass</strong> for table-scoped work; use the <a href="/4d-dataexplorer/guide/assistant.html">chat assistant</a> for broader multi-step help across the app</li><li>Document your schema in the <a href="/4d-dataexplorer/guide/metadata-editor.html">Assistant Metadata Editor</a> so Generate and Ask produce better field values and filters</li><li>Enable or disable assistant tools under <strong>Settings → AI Assistant Tools</strong> if a tool should not be available globally</li></ul><hr>',8))])}const f=o(d,[["render",c]]);export{k as __pageData,f as default};
